expectscript.body:
#!/usr/bin/expect -f
# Kotl runs this with the job's console attached.
set timeout 600
expect {
  "login:" { send "root\r" }
  timeout  { exit 2 }
}
expect "# "
send "/root/my_test\r"
expect {
  "PASS"  { set rc 0 }
  "FAIL"  { set rc 1 }
  timeout { exit 2 }
}
send "poweroff\r"
exit $rc
